#!/usr/bin/env python3
"""Run the original complete CKAN-REMOTE-PUBLICATION-814B-20261013 programme."""
import argparse,base64,hashlib,json,os,pathlib,urllib.request
SOURCE_COMMIT="07be25ede5d9bb9b5c953d8a1a78502265571eb7"
SOURCE_URL="https://raw.githubusercontent.com/woahwhattheheck/tjlabs-stellar-merchant-workspace/"+SOURCE_COMMIT+"/operations/ckan-datastore-acquisition-814b-20261013/source-packet.json"
SOURCE_BLOB="0ac2cd11b4d90c20430a55a73ac9dd4c1de2b70e"
SOURCE_BYTES=6139200
PROGRAMME=base64.b64decode("").decode("utf8")
RUNNER=base64.b64decode("").decode("utf8")
def original_source(options):
    if options.source_packet:
        raw=pathlib.Path(options.source_packet).read_bytes()
    else:
        with urllib.request.urlopen(SOURCE_URL,timeout=90) as response:
            raw=response.read(SOURCE_BYTES+1)
    if len(raw)!=SOURCE_BYTES or hashlib.sha1(b"blob "+str(len(raw)).encode()+b"\0"+raw).hexdigest()!=SOURCE_BLOB:
        raise ValueError("Complete original source packet identity mismatch")
    packet=json.loads(raw)
    if packet["operation"]!="CKAN-DATASTORE-ACQUISITION-814B-20261013" or len(packet["files"])!=365:
        raise ValueError("Original programme source membership mismatch")
    files={};blobs={}
    for row in packet["files"]:
        path=pathlib.PurePosixPath(row["path"])
        if path.is_absolute() or ".." in path.parts or row["path"] in files:
            raise ValueError("Original source member")
        body=row["content"].encode("utf8")
        if hashlib.sha1(b"blob "+str(len(body)).encode()+b"\0"+body).hexdigest()!=row["blobSha"]:
            raise ValueError("Original source body mismatch")
        files[row["path"]]=row["content"];blobs[row["path"]]=row["blobSha"]
    return files,blobs
def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--work-directory",required=True)
    parser.add_argument("--capture","--capture-archive",dest="capture_archive",required=True)
    parser.add_argument("--source-packet")
    parser.add_argument("--node")
    parser.add_argument("--node-modules")
    parser.add_argument("--browser","--browser-executable",dest="browser_executable")
    options=parser.parse_args()
    capture=pathlib.Path(options.capture_archive).absolute()
    if capture.is_symlink() or not capture.is_file() or capture.stat().st_size!=434557:
        raise ValueError("Use the original complete434557-byte capture archive")
    with capture.open("rb") as incoming:
        if hashlib.file_digest(incoming,"sha256").hexdigest()!="b093a0a66b12830f7daf507980b77a9f6f692e22dcf44cd195ef2e599998979c":
            raise ValueError("Original capture archive SHA mismatch")
    if options.node:os.environ["CODEX_PRIMARY_RUNTIME_NODE"]=str(pathlib.Path(options.node).absolute())
    if options.node_modules:os.environ["CODEX_PRIMARY_RUNTIME_NODE_MODULES"]=str(pathlib.Path(options.node_modules).absolute())
    work=pathlib.Path(options.work_directory).absolute()
    if work.exists() or work.is_symlink():
        raise ValueError("Preserve the existing operation directory; select a new private directory")
    work.parent.mkdir(parents=True,exist_ok=True)
    files,blobs=original_source(options)
    payload={"files":files,"sourceBlobs":blobs,"program":PROGRAMME,"workDirectory":str(work),
        "transfer":{"download_url":capture.as_uri(),"method":"GET","headers":{}},
        "browserExecutable":str(pathlib.Path(options.browser_executable).absolute()) if options.browser_executable else None}
    exec(compile(RUNNER,"<original-remote-publication-runner>","exec"),{"payload":payload,"__name__":"__main__"})
if __name__=="__main__":main()
